import{_ as s,r as i,o as e,c as n,a as t,b as r,d as p,e as h}from"./app.ChrdILIc.js";import"./chunks/three-vendor.DK3fmyXa.js";const S=JSON.parse('{"title":"PaaS 介绍与使用","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech-tools/paas.md","filePath":"zh/tech-tools/paas.md","lastUpdated":1778395361000}'),d={name:"zh/tech-tools/paas.md"};function o(k,a,c,u,b,g){const l=i("ArticleMetadata");return e(),n("div",null,[a[0]||(a[0]=t("h1",{id:"paas-介绍与使用",tabindex:"-1"},[r("PaaS 介绍与使用 "),t("a",{class:"header-anchor",href:"#paas-介绍与使用","aria-label":'Permalink to "PaaS 介绍与使用"'},"​")],-1)),p(l),a[1]||(a[1]=h(`<p>PaaS 是 <code>Platform as a Service</code> 的缩写，中文通常叫“平台即服务”。它位于 IaaS 和 SaaS 之间：用户主要关注应用代码、业务配置和数据模型，平台负责运行环境、发布流程、中间件、弹性伸缩、监控等基础能力。</p><p>简单理解：PaaS 不是直接给你一台服务器，也不是直接给你一个完整软件，而是给你一个可以托管、运行和管理应用的平台。</p><h2 id="常见例子" tabindex="-1">常见例子 <a class="header-anchor" href="#常见例子" aria-label="Permalink to &quot;常见例子&quot;">​</a></h2><ul><li>应用托管平台：上传代码或镜像后自动构建、部署和运行。</li><li>Serverless 平台：按函数或服务运行，按请求和资源使用量计费。</li><li>云数据库、云缓存、消息队列等托管中间件。</li><li>容器平台、Kubernetes 托管服务、镜像构建平台。</li><li>低代码/无代码平台中的应用运行和发布能力。</li></ul><h2 id="paas-解决什么问题" tabindex="-1">PaaS 解决什么问题 <a class="header-anchor" href="#paas-解决什么问题" aria-label="Permalink to &quot;PaaS 解决什么问题&quot;">​</a></h2><ul><li><strong>减少运维负担</strong>：不用从零安装运行时、数据库、负载均衡和监控。</li><li><strong>提升交付效率</strong>：代码提交后可以自动构建、部署、回滚。</li><li><strong>统一运行环境</strong>：开发、测试、生产环境更容易保持一致。</li><li><strong>支持弹性伸缩</strong>：根据访问量调整实例数、资源规格或函数并发。</li><li><strong>沉淀平台能力</strong>：日志、告警、配置、密钥、域名、证书可以统一管理。</li></ul><h2 id="核心特点" tabindex="-1">核心特点 <a class="header-anchor" href="#核心特点" aria-label="Permalink to &quot;核心特点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">特点</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">面向开发者</td><td style="text-align:left;">主要服务应用开发、部署和运行</td></tr><tr><td style="text-align:left;">屏蔽底层资源</td><td style="text-align:left;">不需要直接管理物理机或大量系统细节</td></tr><tr><td style="text-align:left;">自动化交付</td><td style="text-align:left;">支持构建、部署、扩缩容、回滚等流程</td></tr><tr><td style="text-align:left;">托管中间件</td><td style="text-align:left;">数据库、缓存、队列等由平台提供或集成</td></tr><tr><td style="text-align:left;">可观测性</td><td style="text-align:left;">通常内置日志、指标、链路追踪和告警</td></tr></tbody></table><h2 id="使用-paas-的基本流程" tabindex="-1">使用 PaaS 的基本流程 <a class="header-anchor" href="#使用-paas-的基本流程" aria-label="Permalink to &quot;使用 PaaS 的基本流程&quot;">​</a></h2><h3 id="_1-准备应用" tabindex="-1">1. 准备应用 <a class="header-anchor" href="#_1-准备应用" aria-label="Permalink to &quot;1. 准备应用&quot;">​</a></h3><p>应用需要具备清晰的启动方式，例如：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>或使用 Docker 镜像描述运行环境：</p><div class="language-dockerfile vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node:22-alpine</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WORKDIR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /app</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package*.json ./</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm ci --omit=dev</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> . .</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RUN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm run build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXPOSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 3000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CMD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="_2-配置运行环境" tabindex="-1">2. 配置运行环境 <a class="header-anchor" href="#_2-配置运行环境" aria-label="Permalink to &quot;2. 配置运行环境&quot;">​</a></h3><p>常见配置包括：</p><ul><li>Node、Java、Python、Go 等运行时版本。</li><li>环境变量和密钥。</li><li>数据库、缓存、对象存储等连接信息。</li><li>启动命令、健康检查、端口。</li><li>域名、HTTPS 证书和访问策略。</li></ul><p>不要把密码、Token、私钥直接写进代码仓库，应使用平台提供的环境变量或密钥管理能力。</p><h3 id="_3-设置发布流程" tabindex="-1">3. 设置发布流程 <a class="header-anchor" href="#_3-设置发布流程" aria-label="Permalink to &quot;3. 设置发布流程&quot;">​</a></h3><p>常见发布方式：</p><ul><li>连接 Git 仓库，推送后自动部署。</li><li>上传构建产物或 Docker 镜像。</li><li>使用 CLI 或 CI/CD 工作流触发发布。</li><li>蓝绿发布、灰度发布或滚动发布。</li></ul><p>生产环境要关注回滚能力，确保出问题时可以快速恢复到旧版本。</p><h3 id="_4-观察运行状态" tabindex="-1">4. 观察运行状态 <a class="header-anchor" href="#_4-观察运行状态" aria-label="Permalink to &quot;4. 观察运行状态&quot;">​</a></h3><p>上线后需要持续关注：</p><ul><li>应用日志。</li><li>CPU、内存、磁盘、网络。</li><li>请求量、响应时间、错误率。</li><li>数据库连接数和慢查询。</li><li>告警通知是否能及时触达负责人。</li></ul><p>PaaS 可以降低运维门槛，但不能替代基本的监控和故障处理意识。</p><h2 id="paas-的优点" tabindex="-1">PaaS 的优点 <a class="header-anchor" href="#paas-的优点" aria-label="Permalink to &quot;PaaS 的优点&quot;">​</a></h2><ul><li>比直接使用云服务器更省运维。</li><li>比 SaaS 更灵活，可以部署自己的业务代码。</li><li>更容易实现标准化部署和持续交付。</li><li>可以复用平台的监控、日志、扩缩容和安全能力。</li><li>适合中小团队快速搭建稳定的应用运行环境。</li></ul><h2 id="paas-的风险" tabindex="-1">PaaS 的风险 <a class="header-anchor" href="#paas-的风险" aria-label="Permalink to &quot;PaaS 的风险&quot;">​</a></h2><ul><li><strong>平台绑定</strong>：部署配置、日志、数据库和扩缩容方式可能依赖特定厂商。</li><li><strong>底层控制有限</strong>：遇到特殊网络、系统参数或性能调优时不如 IaaS 灵活。</li><li><strong>成本不透明</strong>：按请求、存储、流量、实例数计费时需要持续观察账单。</li><li><strong>冷启动或限制</strong>：Serverless 等模式可能有启动延迟、执行时长和并发限制。</li><li><strong>迁移成本</strong>：从一个 PaaS 迁移到另一个平台，可能需要调整配置和架构。</li></ul><h2 id="什么时候适合-paas" tabindex="-1">什么时候适合 PaaS <a class="header-anchor" href="#什么时候适合-paas" aria-label="Permalink to &quot;什么时候适合 PaaS&quot;">​</a></h2><p>适合选择 PaaS 的场景：</p><ul><li>有自己的业务代码，但不想维护太多服务器细节。</li><li>希望快速搭建测试环境、预发环境和生产环境。</li><li>应用访问量波动明显，需要弹性扩缩容。</li><li>团队希望把部署、日志、告警、回滚标准化。</li><li>中间件希望使用托管版本，减少备份和升级压力。</li></ul><p>不太适合 PaaS 的场景：</p><ul><li>需要深度控制操作系统、网络和底层性能参数。</li><li>运行环境非常特殊，平台无法支持。</li><li>对成本模型极其敏感，且自建运维能力成熟。</li><li>对厂商绑定非常排斥，需要跨云完全一致。</li></ul><h2 id="和-iaas、saas-的区别" tabindex="-1">和 IaaS、SaaS 的区别 <a class="header-anchor" href="#和-iaas、saas-的区别" aria-label="Permalink to &quot;和 IaaS、SaaS 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">模型</th><th style="text-align:left;">你主要负责</th><th style="text-align:left;">服务商主要负责</th><th style="text-align:left;">适合人群</th></tr></thead><tbody><tr><td style="text-align:left;">IaaS</td><td style="text-align:left;">系统、运行时、中间件、应用、监控</td><td style="text-align:left;">计算、存储、网络等基础设施</td><td style="text-align:left;">运维能力较强、需要高控制权的团队</td></tr><tr><td style="text-align:left;">PaaS</td><td style="text-align:left;">应用代码、环境变量、业务配置</td><td style="text-align:left;">运行平台、构建发布、扩缩容、日志监控</td><td style="text-align:left;">希望快速交付应用的研发团队</td></tr><tr><td style="text-align:left;">SaaS</td><td style="text-align:left;">账号、权限、业务流程配置</td><td style="text-align:left;">完整软件产品和底层平台</td><td style="text-align:left;">需要直接使用成熟软件的业务团队</td></tr></tbody></table><p>IaaS 更像“租服务器”，PaaS 更像“租应用运行平台”，SaaS 更像“直接租软件”。</p><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to &quot;实践建议&quot;">​</a></h2><ul><li>新项目可以优先用 PaaS 快速上线，再根据规模决定是否下沉到 IaaS 或 Kubernetes。</li><li>环境变量、密钥、数据库连接要统一管理，避免散落在代码和个人电脑中。</li><li>尽量使用标准协议和 Docker 镜像，降低平台迁移成本。</li><li>对核心服务开启健康检查、日志采集、告警和自动回滚。</li><li>定期复盘账单，避免流量、日志、构建次数或存储费用持续增长。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>PaaS 的价值是让开发者专注写业务代码，把构建、部署、扩缩容、监控等通用平台能力交给云平台或内部平台。它比 SaaS 更灵活，比 IaaS 更省运维。</p>`,42))])}const f=s(d,[["render",o]]);export{S as __pageData,f as default};
